package hn.uth.pm1ea0199.view;
import android.app.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public class Vistas {
 public static int dp(Activity a,int n){return (int)(n*a.getResources().getDisplayMetrics().density);}
 public static GradientDrawable fondo(int color,int borde,int radio){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radio);d.setStroke(2,borde);return d;}
 public static LinearLayout pagina(Activity a,String titulo){LinearLayout l=new LinearLayout(a);l.setOrientation(1);l.setBackgroundColor(Color.WHITE);l.setPadding(dp(a,14),dp(a,12),dp(a,14),dp(a,12));l.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(a,14),i.getSystemWindowInsetTop()+dp(a,8),dp(a,14),i.getSystemWindowInsetBottom()+dp(a,8));return i.consumeSystemWindowInsets();});return l;}
 public static LinearLayout fila(Activity a,LinearLayout l){LinearLayout r=new LinearLayout(a);r.setOrientation(0);l.addView(r,new LinearLayout.LayoutParams(-1,-2));return r;}
 public static Button boton(Activity a,LinearLayout l,String texto){Button v=new Button(a);v.setText(texto);v.setTextSize(13);v.setTextColor(Color.BLACK);v.setAllCaps(false);v.setMinHeight(0);v.setMinimumHeight(0);v.setPadding(4,4,4,4);v.setBackground(fondo(Color.WHITE,Color.DKGRAY,0));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(a,44));lp.setMargins(3,5,3,3);l.addView(v,lp);return v;}
 public static Button mitad(Activity a,LinearLayout l,String texto){Button v=boton(a,l,texto);LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)v.getLayoutParams();lp.width=0;lp.weight=1;v.setLayoutParams(lp);return v;}
 public static Button principal(Activity a,LinearLayout l,String texto,int color){Button v=boton(a,l,texto);v.setTextColor(Color.WHITE);v.setBackground(fondo(color,Color.BLACK,0));LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)v.getLayoutParams();lp.width=dp(a,240);lp.gravity=Gravity.CENTER_HORIZONTAL;v.setLayoutParams(lp);return v;}
 public static void etiqueta(Activity a,LinearLayout l,String texto){TextView t=new TextView(a);t.setText(texto);t.setTextColor(Color.DKGRAY);t.setPadding(0,8,0,2);l.addView(t);}
 public static EditText campo(Activity a,LinearLayout l,String etiqueta,int tipo){etiqueta(a,l,etiqueta);EditText e=new EditText(a);e.setSingleLine(true);e.setInputType(tipo);e.setTextSize(16);e.setTextColor(Color.rgb(0,145,45));e.setPadding(dp(a,10),dp(a,5),dp(a,10),dp(a,5));e.setBackground(fondo(Color.WHITE,Color.DKGRAY,dp(a,18)));l.addView(e,new LinearLayout.LayoutParams(-1,dp(a,44)));return e;}
 public static ImageView foto(Activity a,LinearLayout l){ImageView i=new ImageView(a);i.setContentDescription("Fotografía del contacto");i.setScaleType(ImageView.ScaleType.CENTER_INSIDE);i.setImageResource(android.R.drawable.ic_menu_myplaces);i.setBackground(fondo(Color.WHITE,Color.DKGRAY,0));l.addView(i,new LinearLayout.LayoutParams(-1,dp(a,150)));return i;}
 public static void mostrar(ImageView i,String ruta){if(ruta==null||ruta.isEmpty())return;BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(ruta,o);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1000||o.outHeight/o.inSampleSize>1000)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(ruta,o);if(b!=null)i.setImageBitmap(b);else i.setImageResource(android.R.drawable.ic_menu_report_image);}
 public static void alerta(Activity a,String s){new AlertDialog.Builder(a).setTitle("Alerta").setMessage(s).setPositiveButton("Aceptar",null).show();}
 public static String numero(String pais,String tel){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\(([0-9]+)\\)").matcher(pais);if(m.find())return "+"+m.group(1)+tel;String[] nombres={"Honduras","Costa Rica","Guatemala","El Salvador","Nicaragua","Panamá","Belice"};String[] codigos={"504","506","502","503","505","507","501"};for(int i=0;i<nombres.length;i++)if(nombres[i].equals(pais))return "+"+codigos[i]+tel;return tel;}
 public static String numeroVisible(String pais,String tel){String n=numero(pais,tel);return n.substring(0,n.length()-tel.length())+" "+tel.substring(0,4)+"-"+tel.substring(4);}
}
